import AppKit
import ApplicationServices
import Foundation

/// Device-bound action runner for `apple.computer_use`.
///
/// MVP backend: invoke the local Peekaboo CLI and parse its `--json` output.
/// Peekaboo's npm package is also a binary distribution (`@steipete/peekaboo`),
/// so this works with Homebrew, npm/npx-installed binaries, or a future helper
/// bundled in Owletto.app/Contents/Resources. The TS connector declares the
/// action schema; execution must happen here on the permission-bearing Mac.
@MainActor
final class MacComputerUseActionService {
    static let shared = MacComputerUseActionService()

    private init() {}

    /// Soft status check after a grant flow — never calls request APIs that
    /// re-show the system permission sheet (those belong in AppState only).
    func triggerPermissionProbes() async {
        _ = try? await permissions()
        guard CGPreflightScreenCaptureAccess() else { return }
        _ = try? listWindowsNative(["app": .string("frontmost")])
    }

    func run(job: WorkerJob) async throws -> [String: AnyEncodable] {
        guard job.connector_key == "apple.computer_use" else {
            throw ComputerUseError.invalidJob("Expected apple.computer_use, got \(job.connector_key ?? "<nil>")")
        }
        guard let operation = job.operation_key else {
            throw ComputerUseError.invalidJob("Action job missing operation_key")
        }
        let input = job.action_input ?? [:]
        let output: [String: Any]
        switch operation {
        case "permissions": output = try await permissions()
        case "list_apps": output = try listAppsNative()
        case "list_windows": output = try await listWindows(input)
        case "screenshot": output = try screenshotNative(input)
        case "observe": output = try await observe(input)
        case "click": output = try await click(input)
        case "type_text": output = try typeTextNative(input)
        case "paste_text": output = try pasteTextNative(input)
        case "hotkey": output = try hotkeyNative(input)
        case "move_mouse": output = try moveMouseNative(input)
        case "scroll":
            output = (input.string("target") != nil || input.string("snapshot_id") != nil)
                ? try await scrollViaPeekaboo(input)
                : try scrollNative(input)
        case "focus_window":
            output = input.string("window_title") != nil
                ? try await focusWindowViaPeekaboo(input)
                : try focusWindowNative(input)
        case "launch_app": output = try launchAppNative(input)
        default:
            throw ComputerUseError.invalidJob("Unsupported apple.computer_use action '\(operation)'")
        }
        var withMeta = output
        withMeta["operation_key"] = operation
        withMeta["success"] = true

