=== how does the Mac app discover/register these manifests? ===
import Foundation

enum DeviceConnectorManifests {
    static func load() -> [[String: AnyEncodable]] {
        let urls = manifestURLs()
        var manifests: [[String: AnyEncodable]] = []
        for url in urls.sorted(by: { $0.lastPathComponent < $1.lastPathComponent }) {
            guard
                let data = try? Data(contentsOf: url),
                let object = try? JSONSerialization.jsonObject(with: data) as? [String: Any]
            else { continue }
            manifests.append(object.mapValues { AnyEncodable($0) })
        }
        return manifests
    }

    private static func manifestURLs() -> [URL] {
        if let urls = Bundle.main.urls(forResourcesWithExtension: "json", subdirectory: "ConnectorManifests"), !urls.isEmpty {
            return urls
        }
        // Xcode unit-test/dev fallback when resources are not copied into the
        // bundle yet. Production builds use the bundled folder above.
        let sourceDir = URL(fileURLWithPath: #filePath)
            .deletingLastPathComponent()
            .appendingPathComponent("ConnectorManifests", isDirectory: true)
        return (try? FileManager.default.contentsOfDirectory(
            at: sourceDir,
            includingPropertiesForKeys: nil
        ).filter { $0.pathExtension == "json" }) ?? []
    }
}

