struct AnyEncodable: Encodable {
    private let encodeImpl: (Encoder) throws -> Void
    init<T: Encodable>(_ value: T) { self.encodeImpl = value.encode(to:) }
    init(_ value: Any?) {
        switch value {
        case nil, is NSNull:
            self.encodeImpl = { encoder in var c = encoder.singleValueContainer(); try c.encodeNil() }
        case let v as String:
            self.encodeImpl = { encoder in var c = encoder.singleValueContainer(); try c.encode(v) }
        case let v as NSNumber:
            let isBool = CFGetTypeID(v) == CFBooleanGetTypeID()
            if isBool {
                self.encodeImpl = { encoder in var c = encoder.singleValueContainer(); try c.encode(v.boolValue) }
            } else if CFNumberIsFloatType(v) {
