            } else {
                self.encodeImpl = { encoder in var c = encoder.singleValueContainer(); try c.encode(v.intValue) }
            }
        case let v as Bool:
            self.encodeImpl = { encoder in var c = encoder.singleValueContainer(); try c.encode(v) }
        case let v as Int:
            self.encodeImpl = { encoder in var c = encoder.singleValueContainer(); try c.encode(v) }
        case let v as Double:
            self.encodeImpl = { encoder in var c = encoder.singleValueContainer(); try c.encode(v) }
        case let v as [String: AnyEncodable]:
            self.encodeImpl = { encoder in
                var c = encoder.container(keyedBy: DynamicCodingKey.self)
                for (key, value) in v { try c.encode(value, forKey: DynamicCodingKey(key)) }
