import Foundation

/// Device-bound action runner for `os.shell`.
///
/// Executes shell commands as the signed-in user via `zsh -l -c` and returns
/// structured stdout/stderr/exit_code. This is the same trust tier as
/// `apple.computer_use` — commands run in the user's real environment (host
/// PATH, `gh`, files). There is intentionally NO confinement layer here:
/// isolation is a separate axis handled by the sandbox-provider feature. The
/// device advertises `os.shell` only after the user explicitly enables it, so
/// nothing claims runs until the human opts in.
///
/// Process I/O mirrors the proven pattern in `WatcherDispatcher`: inherit the
/// user environment, augment PATH for GUI-launch stripping, drain stdout/stderr
/// concurrently under byte caps (a full pipe deadlocks the SIGTERM-on-timeout
/// path), and bound the run with SIGTERM → 3s grace → SIGKILL.
MacShellActionService: NSObject {
    static let shared = MacShellActionService()
    private override init() { super.init() }

    private static let stdoutCap = 4 * 1024 * 1024
    private static let stderrCap = 1 * 1024 * 1024
    private static let stdinCap = 1 * 1024 * 1024
    private static let defaultTimeoutMs = 60_000
    private static let maxTimeoutMs = 300_000
    private static let minTimeoutMs = 100
    private static let killGraceSeconds: UInt64 = 3

    func run(job: WorkerJob) async throws -> [String: AnyEncodable] {
        guard job.connector_key == "os.shell" else {
            throw ShellError.invalidJob("Expected os.shell, got \(job.connector_key ?? "<nil>")")
        }
        guard let operation = job.operation_key else {
            throw ShellError.invalidJob("Shell job missing operation_key")
        }
        guard operation == "run" else {
            throw ShellError.invalidJob("Unsupported os.shell action '\(operation)'")
        }
        let input = job.action_input ?? [:]
        guard let command = input.string("command"), !command.isEmpty else {
            throw ShellError.invalidInput("run requires a non-empty 'command' string")
        }

        // Working directory. Default to home; require an absolute, existing path.
        let home = NSHomeDirectory()
        let cwd: String
        if let requested = input.string("cwd"), !requested.isEmpty {
            // Reject relative paths — the agent must name an absolute dir so the
            // working dir is unambiguous regardless of how the app was launched.
            guard (requested as NSString).isAbsolutePath else {
                throw ShellError.invalidInput("cwd must be an absolute path, got '\(requested)'")
            }
            guard FileManager.default.fileExists(atPath: requested) else {
                throw ShellError.invalidInput("cwd does not exist: \(requested)")
            }
            cwd = requested
        } else {
            cwd = home
        }

        let timeoutMs = clampedTimeout(input.int("timeout_ms"))
        let stdinString = input.string("stdin")
        if let s = stdinString, s.utf8.count > Self.stdinCap {
            throw ShellError.invalidInput("stdin exceeds \(Self.stdinCap) byte cap")
        }

        let output = await execute(
            command: command,
            cwd: cwd,
            timeoutMs: timeoutMs,
            stdin: stdinString
        )
        var withMeta = output
        withMeta["operation_key"] = "run"
        return withMeta.mapValues { AnyEncodable($0) }
    }

    /// Clamp the requested timeout to the allowed window. Missing/non-finite
    /// falls back to the default rather than throwing — agents routinely omit it.
    private func clampedTimeout(_ raw: Int?) -> Int {
        guard let raw, raw.isFinite else { return Self.defaultTimeoutMs }
        if raw < Self.minTimeoutMs { return Self.minTimeoutMs }
        if raw > Self.maxTimeoutMs { return Self.maxTimeoutMs }
        return raw
    }

    /// Spawn `zsh -l -c <command>` and collect output. All blocking I/O happens
    /// via detached drain tasks and a polling wait loop, so this never pins the
    /// main actor.
    private func execute(command: String, cwd: String, timeoutMs: Int, stdin: String?) async -> [String: Any] {
        let process = Process()
        process.executableURL = URL(fileURLWithPath: "/bin/zsh")
        // Login shell so the user's profile (PATH, nvm, brew shellenv, …) is
        // sourced — that's what makes host-installed CLIs like `gh` resolve.
        process.arguments = ["-l", "-c", command]

        // Inherit the user environment, then repair the stripped GUI-launch PATH
        // so Homebrew / bun / local bins resolve even though a LaunchAgent start
        // leaves a minimal PATH. Mirrors WatcherDispatcher's env setup.
        var env = ProcessInfo.processInfo.environment
        let extraPath = [
            "\(NSHomeDirectory())/.local/bin",
            "\(NSHomeDirectory())/.bun/bin",
            "/opt/homebrew/bin",
            "/usr/local/bin",
        ].joined(separator: ":")
        let path = env["PATH"] ?? "/usr/bin:/bin"
        if !path.contains("/.local/bin") {
            env["PATH"] = "\(extraPath):\(path)"
        }
        process.environment = env
        // Run as the real user. Owletto is already launched as the logged-in
        // user, so this is the default; set it explicitly for clarity.
        process.currentDirectoryURL = URL(fileURLWithPath: cwd)

        let stdoutPipe = Pipe()
        let stderrPipe = Pipe()
        process.standardOutput = stdoutPipe
        process.standardError = stderrPipe

        // stdin: feed the provided string from a detached writer so a large
        // payload can't block the launch on a full pipe. Null device when absent.
        var stdinWriter: Task<Void, Never>?
        if let stdin, !stdin.isEmpty {
            let stdinPipe = Pipe()
            process.standardInput = stdinPipe
            let data = Data(stdin.utf8)
            stdinWriter = Task.detached(priority: .userInitiated) {
                try? stdinPipe.fileHandleForWriting.write(contentsOf: data)
                try? stdinPipe.fileHandleForWriting.close()
            }
        } else {
            process.standardInput = FileHandle.nullDevice
        }

        let stdoutDrain = Self.drainPipe(stdoutPipe, capBytes: Self.stdoutCap)
        let stderrDrain = Self.drainPipe(stderrPipe, capBytes: Self.stderrCap)

        let start = Date()
        do {
            try process.run()
        } catch {
            _ = await stdinWriter?.value
            return [
                "success": false,
                "stdout": "",
                "stderr": "Failed to launch command: \(error.localizedDescription)",
                "exit_code": -1,
                "timed_out": false,
                "duration_ms": Int(Date().timeIntervalSince(start) * 1000),
            ]
        }

        let timedOut = await Self.waitWithTimeout(process: process, timeoutMs: timeoutMs)
        var killSignal: String?
        if timedOut {
            process.terminate() // SIGTERM
            killSignal = "SIGTERM"
            try? await Task.sleep(nanoseconds: Self.killGraceSeconds * 1_000_000_000)
            if process.isRunning {
                kill(process.processIdentifier, SIGKILL)
                killSignal = "SIGKILL"
            }
        }
        // Force-close read handles after a kill so a grandchild that inherited
        // the pipes can't keep the drain blocked. Generous window otherwise.
        let drainDeadlineSeconds: TimeInterval = killSignal == "SIGKILL" ? 2.0 : 60.0
        let (stdoutData, stdoutTruncated) = await Self.awaitDrain(
            stdoutDrain, pipe: stdoutPipe, deadlineSeconds: drainDeadlineSeconds
        )
        let (stderrData, stderrTruncated) = await Self.awaitDrain(
            stderrDrain, pipe: stderrPipe, deadlineSeconds: drainDeadlineSeconds
        )
        _ = await stdinWriter?.value

        let durationMs = Int(Date().timeIntervalSince(start) * 1000)
        var stdout = String(data: stdoutData, encoding: .utf8) ?? ""
        if stdoutTruncated { stdout += "\n[stdout truncated at \(Self.stdoutCap) bytes]" }
        var stderr = String(data: stderrData, encoding: .utf8) ?? ""
        if stderrTruncated { stderr += "\n[stderr truncated at \(Self.stderrCap) bytes]" }

        let exitCode = process.terminationStatus
        return [
            "stdout": stdout,
            "stderr": stderr,
            "exit_code": exitCode,
            "success": !timedOut && exitCode == 0,
            "timed_out": timedOut,
            "duration_ms": durationMs,
        ]
    }

    // MARK: - Process I/O helpers (same technique as WatcherDispatcher)

    /// Read a pipe to EOF under a byte cap, returning the bytes and whether the
    /// cap was hit. Runs detached so the caller can race it against a timeout.
    private static func drainPipe(_ pipe: Pipe, capBytes: Int) -> Task<(Data, Bool), Never> {
        Task.detached(priority: .userInitiated) {
            var accumulated = Data()
            var truncated = false
            let handle = pipe.fileHandleForReading
            while true {
                let chunk = handle.availableData
                if chunk.isEmpty { break } // EOF
                if accumulated.count < capBytes {
                    let room = capBytes - accumulated.count
                    if chunk.count > room { truncated = true }
                    accumulated.append(chunk.prefix(room))
                } else {
                    truncated = true
                }
            }
            return (accumulated, truncated)
        }
    }

    /// Await a drain task with a hard wall-clock deadline; force-close the read
    /// handle if it lapses so the drain's blocking read returns EOF.
    private static func awaitDrain(
        _ task: Task<(Data, Bool), Never>,
        pipe: Pipe,
        deadlineSeconds: TimeInterval
    ) async -> (Data, Bool) {
        let timeoutTask = Task<Void, Never> {
            try? await Task.sleep(nanoseconds: UInt64(deadlineSeconds * 1_000_000_000))
            try? pipe.fileHandleForReading.close()
        }
        let result = await task.value
        timeoutTask.cancel()
        return result
    }

    /// Poll the process until it exits or the timeout lapses. 50ms tick is
    /// plenty — commands run for seconds, and Process exposes no async state.
    private static func waitWithTimeout(process: Process, timeoutMs: Int) async -> Bool {
        let deadline = Date().addingTimeInterval(Double(timeoutMs) / 1000.0)
        while process.isRunning {
            if Date() > deadline { return true }
            try? await Task.sleep(nanoseconds: 50_000_000)
        }
        return false
    }
}

enum ShellError: LocalizedError {
    case invalidJob(String)
    case invalidInput(String)

    var errorDescription: String? {
        switch self {
        case .invalidJob(let msg), .invalidInput(let msg):
            return msg
        }
    }
}

