// Device-bound connector actions. The server enqueues run_type='action'
// for runtime-backed connectors and waits for /complete-action; the Mac
// app must branch before the feed/sync switch below.
if job.run_type == "action" {
    do {
        let output: [String: AnyEncodable]
        switch job.connector_key {
        case "apple.computer_use":
            output = try await MacComputerUseActionService.shared.run(job: job)
        case "os.shell":
            output = try await MacShellActionService.shared.run(job: job)
        default:
            try await worker.completeAction(
                workerId: workerId,
                runId: job.run_id,
                output: nil,
                error: "Mac bridge cannot run action connector \(job.connector_key ?? "<nil>")"
            )
            return CycleResult(claimedJob: true, itemsStreamed: 0, connectorKey: job.connector_key, runId: job.run_id)
        }
        try await worker.completeAction(workerId: workerId, runId: job.run_id, output: output, error: nil)
    } catch {
        try? await worker.completeAction(
            workerId: workerId,
            runId: job.run_id,
            output: nil,
            error: error.localizedDescription
        )
    }
    return CycleResult(claimedJob: true, itemsStreamed: 0, connectorKey: job.connector_key, runId: job.run_id)
}

