  // 1. Find the os.shell connection (or create it)
  const conns = await client.connections.list({ connector_key: "os.shell" });
  let conn = conns.connections?.[0] ?? conns[0];
  let connection_id = conn?.connection_id;

  if (!connection_id) {
    // Create it, device-bound to this Mac
    const devices = await client.operations.listRuns({ run_types: [] }).catch(() => null);
    // Use manage to create — none auth connector
    const created = await client.connections.manage({
      action: "create",
      connector_key: "os.shell",
      display_name: "Mac Mini Shell",
    });
    connection_id = created.connection_id;
    return { step: "created", created, connection_id };
  }

  // 2. Run a command
  const result = await client.operations.execute({
    connection_id,
    operation_id: "run",
    input: { command: "echo 'hello from os.shell e2e'; whoami; pwd; echo EXIT=$?" },
  });

  return { step: "executed", connection_id, result };
}
